function findLargestNumber(arr) {
  if (!arr || arr.length === 0) {
    throw new Error("Array must contain at least one element.");
  }

  let max = arr[0];

  for (let i = 1; i < arr.length; i++) {
    if (arr[i] > max) {
      max = arr[i];
    }
  }

  return max;
}
