function findLargestNumber(arr) {
  if (!arr || arr.length === 0) {
    throw new Error("Array must not be empty.");
  }

  let max = arr[0];

  for (let i = 1; i < arr.length; i++) {
    if (typeof arr[i] !== 'number' || Number.isNaN(arr[i])) {
      throw new Error("Array contains non-numeric or invalid values.");
    }
    if (arr[i] > max) {
      max = arr[i];
    }
  }

  return max;
}
```

